@startuml

class Song {
  + title : string
  + year : int
  + length : time
  + genre : string
}

class Artist {
  + name : string
  + dateOfBirth : date
  + websiteURL : string
}

class User {
  + userID : int
  + name : string
  + address : string
}

class RegularUser {
  + purchaseHistory : string
}

class BusinessUser {
  + VATNumber : string
}

class Single {
}

class Hit {
  + trackNumber : int
}

class Album {
  + title : string
}

class Suggestion {
  + similarityScore : double
}

Song --|> Single
Song --|> Hit

User "1" -- "1" RegularUser
User "1" -- "1" BusinessUser

Artist "1" -- "*" Song

BusinessUser "1" -- "*" Single : uploads
RegularUser "1" -- "*" Single : buys
RegularUser "1" -- "*" Album : composes
Album "1" *-- "1..*" Hit
RegularUser "1" -- "*" Suggestion : receives
RegularUser "1" -- "*" Suggestion : suggests

@enduml

